import { MakeLogicType, actions, afterMount, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { SourceConfigResponseApi } from 'products/warehouse_sources/frontend/generated/api.schemas'

import type { SourceConfigMapResponseApi } from '../../../../warehouse_sources/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface availableSourcesLogicValues {
    availableSources: Record<string, SourceConfigResponseApi> | null
    availableSourcesForbidden: boolean
    availableSourcesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface availableSourcesLogicActions {
    load: () => any
    loadFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSuccess: (
        availableSources: SourceConfigMapResponseApi | null,
        payload?: any
    ) => {
        availableSources: SourceConfigMapResponseApi | null
        payload?: any
    }
    setAvailableSourcesForbidden: (forbidden: boolean) => {
        forbidden: boolean
    }
}

export type availableSourcesLogicType = MakeLogicType<availableSourcesLogicValues, availableSourcesLogicActions>

export const availableSourcesLogic = kea<availableSourcesLogicType>([
    path(['products', 'dataWarehouse', 'availableSourcesLogic']),
    actions({
        setAvailableSourcesForbidden: (forbidden: boolean) => ({ forbidden }),
    }),
    loaders(({ actions }) => ({
        availableSources: [
            null as Record<string, SourceConfigResponseApi> | null,
            {
                load: async () => {
                    try {
                        return await api.externalDataSources.wizard()
                    } catch (e: any) {
                        if (e.status === 403) {
                            actions.setAvailableSourcesForbidden(true)
                            return null
                        }
                        throw e
                    }
                },
            },
        ],
    })),
    reducers({
        // Retrying can't fix a 403, so the error state needs to tell it apart from a timeout or 5xx.
        availableSourcesForbidden: [
            false,
            {
                setAvailableSourcesForbidden: (_, { forbidden }) => forbidden,
                load: () => false,
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.load()
    }),
])
